-- 百人一首100首のデータ（仕様22.1 poems テーブル）
--
-- データの出どころ:
--   ・歌の本文・読み仮名・作者・絵札画像: https://api.aoikujira.com/hyakunin/get2.php?fmt=json
--   ・決まり字: apps/api/src/onboarding-backend/kimariji/kimariji.service.ts
--
-- 実行方法（apps/api ディレクトリで）:
--   set -a; . ./.env; set +a
--   PGPASSWORD="$DB_PASSWORD" psql -h "$DB_HOST" -p "$DB_PORT" -U "$DB_USER" -d "$DB_NAME" \
--     -f src/chihaya/sql/seed_poems.sql
--
-- 何度実行しても結果が同じになるよう、番号が重複したら更新する形にしている
-- （ON CONFLICT ... DO UPDATE）。

ON CONFLICT (number) DO UPDATE SET
  kimariji    = EXCLUDED.kimariji,
  kami        = EXCLUDED.kami,
  shimo       = EXCLUDED.shimo,
  kami_kana   = EXCLUDED.kami_kana,
  shimo_kana  = EXCLUDED.shimo_kana,
  author      = EXCLUDED.author,
  author_kana = EXCLUDED.author_kana,
  image_url   = EXCLUDED.image_url,
  updated_at  = now();
